mapper.update:
UPDATE annotation SET status=#{status},revision=revision+1,updated_at=#{now}
WHERE project_id=#{projectId} AND annotation_id=#{annotationId} AND revision=#{expected} AND status=#{previousStatus}
AND (SELECT COUNT(*) FROM annotation_reply r WHERE r.tenant_id=annotation.tenant_id AND r.project_id=annotation.project_id AND r.annotation_id=annotation.annotation_id)=#{replyCount}
AND EXISTS(SELECT 1 FROM annotation_effective_anchor e WHERE e.tenant_id=annotation.tenant_id AND e.project_id=annotation.project_id
AND e.annotation_id=annotation.annotation_id AND e.anchor_id=#{previousAnchorId} AND e.revision=#{expectedAnchorRevision})

UPDATE operation_record o SET response_ref=#{commandJson},revision=revision+1,updated_at=#{now}
WHERE subject_id=#{userId} AND operation_name='RV-06-REANCHOR-1' AND idempotency_key=#{key}
  AND operation_id=#{operationId} AND target_id=#{annotationId} AND request_sha256=#{requestHash} AND state='PROCESSING' AND revision=#{operationRevision}

UPDATE operation_record o SET state='COMPLETED',http_status=201,response_ref=#{response},revision=revision+1,updated_at=#{now}
WHERE subject_id=#{userId} AND operation_name='RV-06-REANCHOR-1' AND idempotency_key=#{key}
  AND operation_id=#{operationId} AND target_id=#{annotationId} AND request_sha256=#{requestHash} AND state='PROCESSING' AND revision=#{operationRevision}

mapper.select:
SELECT resource_ref FROM audit_event a WHERE subject_id=#{userId} AND project_id=#{projectId} AND action='annotation.reanchored'
  AND result='SUCCESS' AND reason_code IS NULL AND request_id=#{requestId} AND trace_id=#{requestId}
  AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest} AND created_by=#{userId} AND classification=#{classification}
